const trackedEpisodes=()=>allEpisodes().filter(d=>d._workspaceTracked||(d.events||[]).some(e=>!e.baseline&&e.by!=='LOCAL-RESULT-ADAPTER'));
const actor=()=>teamData?.membership?{role:teamData.membership.role,label:teamData.membership.label}:null;
function queue(){const q=FNWorkspaceCore.queue({episodes:trackedEpisodes(),visits:authorizedVisits(),escalations:state.escalations,operator:actor()});for(const r of allResults().filter(r=>r.status!=='cancelled'&&(r.requiresReview&&!r.reviewed||r.reviewKind==='dynamic'&&r.code==='culture'&&r.reviewed&&!r.decision))){if(q.reviews.some(t=>t.patientId===r.patientId&&t.visitId===r.visitId&&t.testId&&t.testId===r.testId))continue;q.reviews.push({patientId:r.patientId,visitId:r.visitId,scope:r.scope,key:r.key,title:r.code+' result',kind:r.reviewed?'Culture decision required':r.reviewKind==='source'?'Flagged source result awaiting review':'Result awaiting review',label:patientName(patients.find(p=>id(p)===r.patientId)||{'Patient ID':r.patientId}),dueAt:null});}q.counts.review=q.reviews.length;return q;}
