const sourceBadge=scope=>`<span class="pill ${scope==='shared'?'':'amber'}">${scope==='shared'?'Shared visit':'Device training'}</span>`;
function teamDashboard(){const q=queue();const filtered=q.tasks.filter(t=>teamFilter==='all'||teamFilter==='mine'&&t.mine||teamFilter==='overdue'&&t.overdue);const items=teamFilter==='review'?q.reviews:filtered;return (window.FNEncounterUI?FNEncounterUI.inbox():'')+title('Team workspace','Your tasks, handovers and decisions in one place.',`<div class="actions"><button class="btn" onclick="refreshTeamWorkspace()">Refresh team</button><button class="btn primary" onclick="fnIntake.open()">New assessment</button></div>`)+notice()+`<div class="shell-kpis">${[['mine','My tasks',q.counts.mine,'Individually assigned to your shared-team identity'],['review','Awaiting review',q.counts.review,'Changed data and reports needing a decision'],['overdue','Overdue actions',q.counts.overdue,'Recorded deadlines on tracked training visits'],['escalation','Open escalations',q.counts.escalation,'Follow response and acknowledgement']].map(([key,label,n,sub])=>`<button class="shell-kpi ${teamFilter===key?'selected':''}" onclick="fnShell.teamFilter('${key}')"><small>${label}</small><strong>${n}</strong><span>${sub}</span></button>`).join('')}</div><section class="panel"><div class="sectiontitle"><div><h2>${teamFilter==='review'?'Review queue':'Action queue'}</h2><p>Role queues are not individual assignments. Device training tasks are labelled separately.</p></div><select aria-label="Task queue" onchange="fnShell.teamFilter(this.value)">${[['all','All open actions'],['mine','My assigned tasks'],['overdue','Overdue actions'],['review','Awaiting review']].map(([k,l])=>`<option value="${k}" ${teamFilter===k?'selected':''}>${l}</option>`).join('')}</select></div>${items.length?`<div class="scroll"><table><thead><tr><th>Patient / encounter</th><th>Required action</th><th>Responsibility</th><th>Due / status</th><th></th></tr></thead><tbody>${items.slice(0,30).map(t=>`<tr><td><b>${esc(t.label)}</b><div class="mini">${esc(t.patientId)}</div>${sourceBadge(t.scope)}</td><td>${esc(t.title)}</td><td>${esc(t.ownerLabel||'Reviewing clinician')}<div class="mini">${esc(t.ownerRole||'physician / pharmacist')}</div></td><td>${t.dueAt?esc(fmt(t.dueAt)):'No deadline recorded'}<div>${t.overdue?'<span class="pill red">Overdue</span>':esc(t.status||t.kind)}</div></td><td>${recordLink(t.patientId,t.visitId,teamFilter==='review'?'Review patient':'Open action plan')}</td></tr>`).join('')}</tbody></table></div>${items.length>30?'<p>First 30 open items shown. Open Follow-up for the full patient action list.</p>':''}`:'<div class="empty"><h3>No items in this queue</h3><p>Open a patient and start tracking the training episode, or load your authorized team visits. No completed care or assignment is assumed.</p><button class="btn" onclick="go(\'Overview\')">Browse patients</button></div>'}</section><details class="shell-team-settings"><summary>Shared team and handovers ${teamBusy?'· refreshing…':''}</summary>${teamSettings()}</details>`;}
function teamSettings(){const signed=teamSession?.signedIn;return `${teamError?`<p class="notice" role="alert">${esc(teamError)}</p>`:''}<p>Shared visits retain their own encounter identity and server-enforced permissions. A patient record can show either the device episode or a specific shared visit; they are never silently combined.</p>${signed?`<div class="actions">${teamSession.workspaces.length?`<label>Team<select aria-label="Team workspace selection" onchange="chooseTeamWorkspace(this.value)">${teamSession.workspaces.map(w=>`<option value="${esc(w.id)}" ${w.id===teamWorkspaceId?'selected':''}>${esc(w.name)} · ${esc(w.role)}</option>`).join('')}</select></label>`:'<p>No shared team assigned.</p>'}${window.fnAccount?.isOwner()?'<button class="btn" onclick="openTeamCreate()">Create training team</button>':''}${teamRoleCan('nurse')?'<button class="btn" onclick="openTeamVisit()">Create shared visit</button>':''}</div>${teamData?teamQueueView()+teamAuditView():''}`:'<p>Refresh team to load the workspaces available to your application account.</p><button class="btn" onclick="refreshTeamWorkspace()">Load my team</button>'}`;}
const previousQueue=teamQueueView;teamQueueView=function(){if(!teamData)return '';return `<section class="panel"><h2>Shared visits</h2><div class="scroll"><table><thead><tr><th>Patient / visit</th><th>Handover</th><th>Updated</th><th></th></tr></thead><tbody>${teamData.visits.map(v=>`<tr><td>${esc(v.case_code)}<div class="mini">Visit ${esc(v.id.slice(0,8))}</div></td><td>${esc(teamStages[v.stage]?.label||v.stage)}</td><td>${esc(fmt(v.updated_at))}</td><td>${recordLink(v.case_code,v.id)}</td></tr>`).join('')||'<tr><td colspan="4">No shared visits yet.</td></tr>'}</tbody></table></div></section>`;};
function resources(){return title('Resources & administration','Reference material, training and management tools, separate from daily care.')+`<div class="shell-resource-grid">${[['Clinical references','FN guidelines, evidence, MASCC, renal references and the data dictionary.','fnGuidelines.open()'],['Scenario library','All teaching scenarios, worked examples and source pathways.','go(\'Scenario library\')'],['Quality & value','Recorded use, clinical measures and financial scenarios.','go(\'Quality & value\')'],['Governance & settings','Safety, rules, audit history and account administration.','go(\'Governance & settings\')']].map(([h,p,action])=>`<button class="panel shell-resource" onclick="${action}">${svg('book')}<h2>${h}</h2><p>${p}</p><span>Open section →</span></button>`).join('')}</div>`;}
function management(kind){const items=kind==='Quality & value'?[['Recorded use','Timing and completion measures from documented synthetic work.','fnDyn.tab(\'Measured use\');go(\'Dynamic reassessment\')'],['Clinical quality','Review process measures, denominators and missing data.','go(\'Clinical quality\')'],['Financial impact','Review hypothetical financial assumptions and scenarios.','go(\'Financial impact\')']]:[['Safety & process','Safety gaps and process controls.','go(\'Safety & process\')'],['Alert governance','Rules, knowledge ownership and review status.','go(\'Alert governance\')'],['Audit trail','Recorded actions and provenance.','go(\'Audit trail\')'],['Scope & evidence','Application boundaries and supporting references.','go(\'Scope & evidence\')'],['My account','Profile and account settings.','fnAccount.load()'],...(window.fnAccount?.isOwner()?[['Registered users','Owner-only account administration.','fnAccount.admin()']]:[])];return title(kind,'Choose a management tool.',`<button class="btn" onclick="go('Resources')">Back to resources</button>`)+`<div class="shell-resource-grid">${items.map(([h,p,a])=>`<button class="panel shell-resource" onclick="${a}"><h2>${h}</h2><p>${p}</p></button>`).join('')}</div>`;}
function scenarioLibrary(){const examples=fnDyn.examplesList();const entries=patients.filter(p=>/^WB-|^SIM-A2A-|^WALK-/.test(id(p))||examples.some(e=>e.patientId===id(p)));const rows=entries.filter(p=>JSON.stringify([patientName(p),id(p),p.Diagnosis]).toLowerCase().includes(scenarioQuery.toLowerCase())&&(scenarioGroup==='All'||assess(p).risk===scenarioGroup));const max=Math.max(0,Math.ceil(rows.length/9)-1);scenarioPage=Math.min(scenarioPage,max);return title('Scenario library','One collection of fictional cases. Open a patient to assess, review results and follow changes.',`<button class="btn" onclick="go('Resources')">Resources</button>`)+notice()+`<div class="tools"><input aria-label="Search scenarios" placeholder="Find a name, case ID or diagnosis" value="${esc(scenarioQuery)}" onchange="fnShell.scenarioSearch(this.value)"><select aria-label="Scenario risk" onchange="fnShell.scenarioGroup(this.value)">${['All','High','Low','Unknown'].map(x=>`<option ${x===scenarioGroup?'selected':''}>${x}</option>`).join('')}</select></div><p>${rows.length} cases · Source workbook scenarios, 20 teaching cases, 10 worked examples and walkthroughs.</p><div class="shell-resource-grid">${rows.slice(scenarioPage*9,scenarioPage*9+9).map(p=>`<article class="panel"><small>${esc(id(p))}</small><h2>${esc(patientName(p))}</h2><p>${esc(p.Diagnosis||'Workbook teaching scenario')}</p>${badge(assess(p).risk)}${recordLink(id(p),'','Open scenario')}</article>`).join('')}</div><div class="pagination"><span>Page ${scenarioPage+1} of ${max+1}</span><div><button class="btn" ${scenarioPage===0?'disabled':''} onclick="fnShell.scenarioPage(-1)">Previous</button><button class="btn" ${scenarioPage===max?'disabled':''} onclick="fnShell.scenarioPage(1)">Next</button></div></div>`;}
function currentRecord(){const v=recordVisit?authorizedVisits().find(v=>v.id===recordVisit&&v.case_code===recordId):null;if(recordVisit&&!v)return null;const local=patients.find(p=>id(p)===recordId);if(recordVisit){const m=v.snapshot.measurements;return {patient:local||{'Patient ID':recordId,'Display name':recordId},visit:v,measurements:{...m},episode:v.snapshot.dynamic||null};}return local?{patient:local,visit:null,episode:state.dynamicEpisodes[recordId]||null}:null;}
function patientRecord(){const rec=currentRecord();if(!rec)return title('Patient record unavailable','Refresh your team access or select an available patient.',`<button class="btn" onclick="go('Overview')">Patients</button>`);const {patient:p,visit:v}=rec;let d=rec.episode;const a=d?{score:d.current.score,risk:d.current.risk}:v?{score:null,risk:'Unknown',flags:['Shared visit needs a complete assessment']}:assess(p);const allergy=v?d?.input.allergy||'Unknown - verify':allergyLabel(recordId);const visits=authorizedVisits().filter(v=>v.case_code===recordId);const last=v?.updated_at||d?.events?.at(-1)?.at||p._savedAt;const headerHtml=`<section class="shell-patient-head"><div><small>PATIENT RECORD · ${esc(recordId)}</small><h1>${esc(patientName(p))}</h1><p>${esc(p.Diagnosis||'Shared synthetic visit')}</p></div><div class="shell-patient-status"><span class="pill ${String(a.risk).includes('High')?'red':String(a.risk).includes('Incomplete')||a.risk==='Unknown'?'amber':''}">${esc(a.risk)}</span><span>MASCC <b>${a.score??'Incomplete'}</b></span><span class="allergy">${esc(allergy)}</span><span>Last activity: ${last?esc(fmt(last)):'No source time supplied'}</span></div><div class="actions"><button class="btn" onclick="go('Overview')">All patients</button><button class="btn primary" onclick="fnShell.follow('${enc(recordId)}','${enc(recordVisit)}')">Open follow-up</button><button class="btn shell-escalate" onclick="fnShell.escalate('${enc(recordId)}')">Escalate</button></div>${visits.length?`<label class="shell-encounter">Encounter<select aria-label="Patient encounter" onchange="fnShell.encounter(this.value)">${patients.some(p=>id(p)===recordId)?`<option value="" ${!recordVisit?'selected':''}>Device training episode</option>`:''}${visits.map(x=>`<option value="${esc(x.id)}" ${recordVisit===x.id?'selected':''}>Shared visit ${esc(x.id.slice(0,8))} · ${esc(fmt(x.snapshot.triageAt))}</option>`).join('')}</select></label>`:''}<p class="mini">${v?'Authorized shared visit · server roles apply':'Device training episode · source workbook values are not live observations'}</p></section><div class="tabs shell-record-tabs">${['Summary','Care plan','Results','Timeline'].map(t=>`<button class="${recordTab===t?'selected':''}" onclick="fnShell.recordTab('${t}')">${t}</button>`).join('')}</div>`;
 let body='';if(recordTab==='Summary'){const input=d?.input;const m=v?.snapshot.measurements;const vals=[['Temperature',v?(input?.temp??m?.temperature):input?.temp??p['Temp (°C)'],'°C'],['ANC',v?(input?.anc??m?.anc):input?.anc??p['ANC (×10⁹/L)'],'×10⁹/L'],['Systolic BP',v?(input?.sbp??m?.systolic):input?.sbp??p['Systolic BP (mmHg)'],'mmHg'],['Creatinine clearance',v?(input?.crcl??m?.crcl):input?.crcl??p['CrCl (mL/min)'],'mL/min']];body=`<div class="grid2"><section class="panel"><h2>Current recorded findings</h2><div class="snapshot">${vals.map(([k,n,u])=>`<div><small>${k}</small><strong>${n===null||n===undefined?'Unknown':esc(n)+' '+u}</strong><span>${d?'Episode inputs - verify freshness':'Source values - measurement time not supplied'}</span></div>`).join('')}</div><h3>Risk explanation</h3><p>${esc((d?.current.reasons||a.flags||[]).join('; ')||'No additional recorded override. Missing information still requires review.')}</p></section><section class="panel"><h2>Next step</h2><p>Review the assessment, agree the care plan, and track execution against this patient and encounter.</p><div class="actions">${!v?`<button class="btn primary" onclick="fnShell.assessment('${enc(recordId)}')">Review assessment</button>`:''}<button class="btn" onclick="fnShell.recordTab('Care plan')">Care plan & actions</button><button class="btn" onclick="fnShell.recordTab('Results')">Review results</button></div>${!v&&/^WB-/.test(recordId)?`<button class="btn" onclick="fnWorkbook.scenario('${recordId.slice(3)}')">Teaching pathway & answer key</button>`:''}</section></div>`+(v?teamDetailView():'');}
 if(recordTab==='Care plan')body=fnDyn.recordPanel(recordId,recordVisit,'plan');
 if(recordTab==='Results'){const rows=allResults().filter(r=>r.patientId===recordId&&r.visitId===recordVisit);body=`<section class="panel"><div class="sectiontitle"><h2>Patient results</h2><button class="btn" onclick="fnShell.follow('${enc(recordId)}','${enc(recordVisit)}','Actions & tests')">Tests, specimens & decisions</button></div>${resultsTable(rows)}</section>`;}
 if(recordTab==='Timeline'){const events=v?(teamData.events||[]).filter(e=>e.visit_id===v.id):[...state.events.filter(e=>e.patient===recordId),...state.careHistory.filter(e=>e.patientId===recordId)];body=`<section class="panel"><h2>Recorded activity</h2>${events.length?events.slice().sort((a,b)=>Date.parse(b.time||b.at)-Date.parse(a.time||a.at)).slice(0,50).map(e=>`<div class="stage"><b>${esc(e.action)}</b><p>${esc(fmt(e.time||e.at))} · ${esc(e.note||'')}</p></div>`).join(''):'<p>No recorded activity for this encounter.</p>'}</section>`+(d?fnDyn.recordPanel(recordId,recordVisit,'timeline'):'');}
 return headerHtml+body+notice();}
function resultsTable(rows){if(!rows.length)return '<div class="empty">No results in this view. Missing results do not mean normal results.</div>';return `<div class="scroll"><table><thead><tr><th>Patient / source</th><th>Result</th><th>Report / time</th><th>Review</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(patientName(patients.find(p=>id(p)===r.patientId)||{'Patient ID':r.patientId}))}</b><div class="mini">${esc(r.patientId)} · ${esc(r.accession)}</div>${sourceBadge(r.scope)}</td><td><b>${esc(r.code)}</b><p>${esc(r.value)} ${esc(r.unit||'')}</p>${r.organism?`<p>${esc(r.organism)}</p>`:''}${r.ast&&Object.keys(r.ast).length?`<p class="mini">Reported AST: ${esc(Object.entries(r.ast).map(([k,v])=>k+': '+v).join(' · '))}</p>`:''}${r.susceptibilities?.length?`<p class="mini">Reported AST: ${esc(r.susceptibilities.map(s=>s.agent+': '+s.interpretation).join(' · '))}</p>`:''}${r.text||r.reportText?`<details><summary>Report details</summary><p>${esc(r.text||r.reportText)}</p></details>`:''}</td><td>${esc(r.status)}<div class="mini">${esc(fmt(r.issuedAt))}</div></td><td><span class="pill ${r.reviewed?'':'amber'}">${r.reviewed?'Reviewed':'Needs review'}</span>${r.decision?'<p>Clinical decision recorded</p>':''}${r.sourceReviewAt?'<p class="mini">Earlier source review retained; current follow-up acknowledgement is separate.</p>':''}<button class="btn" onclick="fnShell.resultReview('${enc(r.key)}')">${r.reviewed?'Review details':'Review result'}</button></td><td>${recordLink(r.patientId,r.visitId)}</td></tr>`).join('')}</tbody></table></div>`;}
function resultsPage(){const all=allResults().filter(r=>!resultPatientFilter||r.patientId===resultPatientFilter);const rows=all.filter(r=>(resultMode==='All results'||resultMode==='Needs review'&&r.requiresReview&&!r.reviewed&&r.status!=='cancelled'||resultMode==='Reviewed'&&r.reviewed)&&JSON.stringify([r.patientId,r.code,r.organism,r.value,r.accession]).toLowerCase().includes(resultQuery.toLowerCase()));const max=Math.max(0,Math.ceil(rows.length/12)-1);resultPage=Math.min(max,resultPage);return title('Results','Patient-matched results, current report versions and review status.',`<button class="btn" onclick="fnShell.resultTools()">Import & connection tools</button>`)+notice()+`<div class="tools"><input aria-label="Search results" placeholder="Patient ID, test, accession or organism" value="${esc(resultQuery)}" onchange="fnShell.resultSearch(this.value)"><select aria-label="Result review status" onchange="fnShell.resultMode(this.value)">${['Needs review','Reviewed','All results'].map(t=>`<option ${t===resultMode?'selected':''}>${t}</option>`).join('')}</select>${resultPatientFilter?'<button class="btn" onclick="fnShell.clearResultPatient()">Show all patients</button>':''}</div><p>${rows.length} matching results · Preliminary, final, corrected and cancelled status is retained. Undated source values remain undated.</p><section class="panel">${resultsTable(rows.slice(resultPage*12,resultPage*12+12))}<div class="pagination"><span>Page ${resultPage+1} of ${max+1}</span><div><button class="btn" ${resultPage===0?'disabled':''} onclick="fnShell.resultPage(-1)">Previous</button><button class="btn" ${resultPage===max?'disabled':''} onclick="fnShell.resultPage(1)">Next</button></div></div></section>`;}
const legacyIntegration=integration;
window.fnShell={discardNavigation(){const action=pendingNavigation;pendingNavigation=null;teamEditing=false;closeDialog();action?.()},resultsHome(){resultPatientFilter='';resultMode='Needs review';resultPage=0;go('Integration')},followHome(){fnDyn.tab('Cases');go('Dynamic reassessment')},patient(pid,visitId='',tab='Summary'){if(blockNavigation(()=>fnShell.patient(pid,visitId,tab)))return;pid=dec(pid);visitId=dec(visitId);if(visitId&&!authorizedVisits().some(v=>v.id===visitId&&v.case_code===pid))return;const p=patients.find(p=>id(p)===pid);if(!p&&!visitId)return;recordId=pid;recordVisit=visitId;recordTab=['Summary','Care plan','Results','Timeline'].includes(tab)?tab:'Summary';selected=p||null;if(visitId)teamVisitId=visitId;go('Patient record')},recordTab(t){if(blockNavigation(()=>fnShell.recordTab(t)))return;if(!['Summary','Care plan','Results','Timeline'].includes(t))return;recordTab=t;render()},encounter(v){if(blockNavigation(()=>fnShell.encounter(v)))return;if(v&&!authorizedVisits().some(x=>x.id===v&&x.case_code===recordId))return;recordVisit=v;teamVisitId=v||teamVisitId;render()},follow(pid,vid='',tab='Cases'){if(blockNavigation(()=>fnShell.follow(pid,vid,tab)))return;try{fnDyn.openContext(dec(pid),dec(vid),tab)}catch(e){openDialog('Visit unavailable',`<p>${esc(e.message)}</p><button class="btn" onclick="closeDialog()">Close</button>`)}},assessment(pid){pid=dec(pid);const c=fnA2A.caseForPatient(pid);if(c){if(c.userEntered)fnIntake.edit(c);else{fnA2A.openCase(c.id)}}else if(/^FN-\d{3}$|^WB-/.test(pid))fnWorkbook.assessment(pid);else{selected=patients.find(p=>id(p)===pid);openAssessment(false)}},escalate(pid){pid=dec(pid);if(!patients.some(p=>id(p)===pid)){go('Escalation center');return;}openEscalation(pid)},teamFilter(v){if(v==='escalation'){go('Escalation center');return;}teamFilter=v;render()},resultMode(v){resultMode=v;resultPage=0;render()},resultSearch(v){resultQuery=v;resultPage=0;render()},resultPage(n){resultPage=Math.max(0,resultPage+n);render()},clearResultPatient(){resultPatientFilter='';render()},resultTools(){go('Result tools')},resultReview(key){const r=allResults().find(r=>r.key===dec(key));if(!r)return;if(r.reviewKind==='dynamic'){try{fnDyn.context(r.patientId,r.visitId);if(r.reviewed){openDialog('Report review recorded',`<p>This version was acknowledged in the patient follow-up record. Acknowledgement does not by itself approve treatment.</p><button class="btn primary" onclick="closeDialog();fnShell.follow('${enc(r.patientId)}','${enc(r.visitId)}','Actions & tests')">Open report and decision</button><button class="btn" onclick="closeDialog()">Close</button>`)}else fnDyn.resultReview(r.testId,false);}catch(e){openDialog('Review unavailable',`<p>${esc(e.message)}</p>`)}}else reviewResult(r.eventId)},scenarioSearch(v){scenarioQuery=v;scenarioPage=0;render()},scenarioGroup(v){scenarioGroup=v;scenarioPage=0;render()},scenarioPage(n){scenarioPage=Math.max(0,scenarioPage+n);render()},queue,allResults,currentRecord};
const dynamicTab=fnDyn.tab;fnDyn.tab=function(t){if(view==='Patient record'&&t==='Actions & tests'){fnShell.follow(enc(recordId),enc(recordVisit),t);return;}dynamicTab(t)};
const patientResults=fnA2A.resultPatient;fnA2A.resultPatient=function(pid){resultMode='All results';resultPage=0;return patientResults(pid)};
