let patientScope='all';
const scopedPatients=()=>patients.filter(p=>patientScope==='all'||(patientScope==='primary'?primary(p):!primary(p)));
const patientRows=()=>scopedPatients().filter(p=>JSON.stringify([id(p),patientName(p),p.Diagnosis]).toLowerCase().includes(search.toLowerCase())&&(filter==='All'||assess(p).risk===filter));
fnShell.patientScope=function(v){if(!['all','primary','secondary'].includes(v))return;patientScope=v;page=0;search='';filter='All';go('Overview')};
overview=function(){const counts={all:patients.length,primary:patients.filter(primary).length,secondary:patients.filter(p=>!primary(p)).length};const rows=patientRows();page=Math.min(page,Math.max(0,Math.ceil(rows.length/perPage)-1));return title('Patients','One registry. Open a patient to assess, track actions or review results.',`<button class="btn primary" onclick="fnIntake.open()">New assessment</button>`)+notice()+`<div class="shell-cohorts" role="group" aria-label="Patient cohorts">${[['all','All patients'],['primary','Primary cohort'],['secondary','Hospital scenarios']].map(([k,l])=>`<button class="${patientScope===k?'selected':''}" aria-pressed="${patientScope===k}" onclick="fnShell.patientScope('${k}')"><span>${l}</span><b>${counts[k]}</b></button>`).join('')}</div><section class="panel"><div class="sectiontitle"><h2>Patient list</h2><span id="shell-patient-count">${rows.length} matching records</span></div><div class="tools"><input id="search" aria-label="Search patients" placeholder="Name, patient ID or diagnosis" value="${esc(search)}" oninput="search=this.value;page=0;refreshRows()"><select aria-label="Risk filter" onchange="filter=this.value;page=0;render()">${['All','High','Low','Unknown'].map(v=>`<option ${v===filter?'selected':''}>${v}</option>`).join('')}</select></div><div id="rows">${compactRows(rows)}</div></section>`;};
refreshRows=function(){const rows=patientRows();document.querySelector('#rows').innerHTML=compactRows(rows);const count=document.querySelector('#shell-patient-count');if(count)count.textContent=rows.length+' matching records';};
const oldRender=render;render=function(){const settingsOpen=!!$app().querySelector('.shell-team-settings[open]');oldRender();if(view==='Team workspace'){$app().innerHTML=teamDashboard();if(settingsOpen)$app().querySelector('.shell-team-settings').open=true;}else if(view==='Patient record')$app().innerHTML=patientRecord();else if(view==='Resources')$app().innerHTML=resources();else if(view==='Scenario library')$app().innerHTML=scenarioLibrary();else if(['Quality & value','Governance & settings'].includes(view))$app().innerHTML=management(view);else if(view==='Integration')$app().innerHTML=resultsPage();else if(view==='Result tools')$app().innerHTML=title('Result tools','Import and connection settings.',`<button class="btn" onclick="go('Integration')">Back to results</button>`)+legacyIntegration();if(view==='Patient assessment'){$app().querySelector('.a2a-library')?.remove();$app().querySelectorAll('button').forEach(b=>{if(['Workbook assessments','← Patient assessment to action · 20 scenarios'].includes(b.textContent.trim()))b.remove()});}if(view==='Overview'){$app().querySelector('.connectioncard')?.remove();$app().querySelector('.demolaunch')?.remove();const h=$app().querySelector('h1');if(h)h.textContent='Patients';}if(view==='Workbook database'){$app().querySelector('h1').textContent='Clinical references';$app().insertAdjacentHTML('afterbegin',`<div class="actions"><button class="btn" onclick="go('Resources')">Resources</button><button class="btn" onclick="fnDyn.tab('Local protocol');go('Dynamic reassessment')">Hospital local protocol</button></div>`);$app().querySelectorAll('.tabs button').forEach(b=>{if(['Patients','Scenarios','Pathways'].includes(b.textContent)){b.hidden=true;}});}};
